// Package httpapi implements the HTTP API on top of the store.
//
// The routing, parameter validation and JSON encoding are generated by ogen
// in internal/gen/api. This package only fills in the generated Handler
// interface: it reads from the store and converts store types to API types.
package httpapi

import (
	"context"
	"log/slog"
	"math"
	"net/http"
	"time"

	"github.com/JermanLuka/hive-telemetry/internal/gen/api"
	"github.com/JermanLuka/hive-telemetry/internal/store"
)

// defaultRange is used when a request gives no "from" time.
const defaultRange = 24 * time.Hour

// Store is what the handler needs from the database layer. *store.Store
// satisfies it; tests can pass a fake instead.
type Store interface {
	ListHives(ctx context.Context) ([]store.Hive, error)
	Readings(ctx context.Context, hiveID string, from, to time.Time, limit int) ([]store.Reading, error)
	Summary(ctx context.Context, hiveID string, from, to time.Time) (store.Summary, error)
}

// Handler implements api.Handler.
type Handler struct {
	store  Store
	logger *slog.Logger
	now    func() time.Time // time.Now, replaceable in tests
}

// Compile-time check that *Handler implements every method of api.Handler.
var _ api.Handler = (*Handler)(nil)

// ListHives implements GET /hives.
func (h *Handler) ListHives(ctx context.Context) ([]api.Hive, error) {
	hives, err := h.store.ListHives(ctx)
	if err != nil {
		return nil, err
	}

	out := make([]api.Hive, 0, len(hives))
	for _, hv := range hives {
		out = append(out, api.Hive{
			ID:        hv.ID,
			Name:      hv.Name,
			CreatedAt: hv.CreatedAt.UTC(),
		})
	}
	return out, nil
}

// ListHiveReadings implements GET /hives/{hiveId}/readings.
func (h *Handler) ListHiveReadings(ctx context.Context, params api.ListHiveReadingsParams) ([]api.Reading, error) {
	from, to, err := h.timeRange(params.From, params.To)
	if err != nil {
		return nil, err
	}

	// ogen has already checked 1 <= limit <= 10000 and filled in the default.
	readings, err := h.store.Readings(ctx, params.HiveId, from, to, params.Limit.Or(1000))
	if err != nil {
		return nil, err
	}

	out := make([]api.Reading, 0, len(readings))
	for _, r := range readings {
		out = append(out, toAPIReading(r))
	}
	return out, nil
}

// GetHiveSummary implements GET /hives/{hiveId}/summary.
func (h *Handler) GetHiveSummary(ctx context.Context, params api.GetHiveSummaryParams) (*api.Summary, error) {
	from, to, err := h.timeRange(params.From, params.To)
	if err != nil {
		return nil, err
	}

	sum, err := h.store.Summary(ctx, params.HiveId, from, to)
	if err != nil {
		return nil, err
	}

	out := &api.Summary{
		HiveID: sum.HiveID,
		From:   sum.From.UTC(),
		To:     sum.To.UTC(),
		Count:  sum.Count,
	}
	if w := sum.Weight; w != nil {
		out.Weight = api.NewOptWeightStats(api.WeightStats{
			MinKg:    w.MinKg,
			MaxKg:    w.MaxKg,
			AvgKg:    round3(w.AvgKg),
			FirstKg:  w.FirstKg,
			LastKg:   w.LastKg,
			ChangeKg: round3(w.ChangeKg()),
		})
	}
	return out, nil
}

// timeRange applies the defaults: "to" is now, "from" is 24 hours before "to".
func (h *Handler) timeRange(fromParam, toParam api.OptDateTime) (from, to time.Time, err error) {
	to = toParam.Or(h.now())
	from = fromParam.Or(to.Add(-defaultRange))
	if !from.Before(to) {
		return time.Time{}, time.Time{}, &api.ErrorStatusCode{
			StatusCode: http.StatusBadRequest,
			Response:   api.Error{Message: "from must be before to"},
		}
	}
	return from, to, nil
}

// round3 rounds to 3 decimals (grams). Averages and differences of
// float64 values pick up noise like 0.8900000000000006.
func round3(x float64) float64 {
	return math.Round(x*1000) / 1000
}

func toAPIReading(r store.Reading) api.Reading {
	out := api.Reading{
		ObservedAt: r.ObservedAt.UTC(),
		ReceivedAt: r.ReceivedAt.UTC(),
		WeightKg:   r.WeightKg,
	}
	if r.TemperatureC != nil {
		out.TemperatureC = api.NewOptFloat64(*r.TemperatureC)
	}
	return out
}
